// Forward-run analysis (DESIGN.md §"Forward run"): the exact McNemar test on the paired pass/fail outcomes,
// the Wilcoxon signed-rank test on the paired costs, and the wording of the claim. Every rule here is
// pre-registered in the backlog task F09, so the numbers a report prints are the ones the run promised.
// Statistics live in experiments/, not in the repo's own evidence: nothing in this file feeds docs/FACTS.md.

/** A forward run may claim a result only from this many counted pairs on. */
export const MIN_CLAIM_PAIRS = 24;
/** Significance level for both tests. */
export const ALPHA = 0.05;

// ---- McNemar exact ----

/**
 * Two-sided exact McNemar test over the discordant counts `b` and `c`.
 * Under the null every discordant pair falls either way with p = 1/2, so the exact two-sided p is
 * `2 * sum_{k <= min(b, c)} C(b + c, k) * 2^-(b + c)`, capped at 1. No discordant pairs means no evidence,
 * so p = 1; the result is symmetric in `b` and `c`.
 */
export function mcnemarExact(b: number, c: number): number {
  const n = b + c;
  if (n <= 0) return 1;
  const k = Math.min(b, c);
  // Sum the tail in log space: C(n, k) * 2^-n overflows a double for large n even when the tail is negligible.
  let logSum = -Infinity;
  let logTerm = -n * Math.LN2; // C(n, 0) * 2^-n
  for (let i = 0; i <= k; i++) {
    if (i > 0) logTerm += Math.log((n - i + 1) / i); // C(n, i) = C(n, i - 1) * (n - i + 1) / i
    logSum = logSum === -Infinity ? logTerm : logAdd(logSum, logTerm);
  }
  return Math.min(1, 2 * Math.exp(logSum));
}

/** log(e^a + e^b) without overflowing. */
function logAdd(a: number, b: number): number {
  const m = Math.max(a, b);
  return m + Math.log(Math.exp(a - m) + Math.exp(b - m));
}

// ---- Wilcoxon signed-rank ----

export interface WilcoxonResult {
  /** Sum of the ranks of the positive differences. */
  w: number;
  /** Two-sided p-value. */
  p: number;
  /** Number of non-zero differences. */
  n: number;
}

/**
 * Two-sided Wilcoxon signed-rank test on the paired differences.
 * Zero differences are dropped from both n and the ranks (they carry no sign); tied absolute differences
 * share their average rank. The exact null distribution is used for n <= 20, the normal approximation
 * (continuity corrected) for n > 20. Fewer than one non-zero difference means no evidence, so p = 1.
 */
export function wilcoxonSignedRank(diffs: number[]): WilcoxonResult {
  const nonZero = diffs.filter((d) => d !== 0);
  const n = nonZero.length;
  if (n === 0) return { w: 0, p: 1, n: 0 };
  const ranks = averageRanks(nonZero.map((d) => Math.abs(d)));
  const w = nonZero.reduce((sum, d, i) => (d > 0 ? sum + ranks[i]! : sum), 0);
  return { w, p: n <= 20 ? exactP(ranks, w, n) : normalP(ranks, w, n), n };
}

/** 1-based ranks of `values`, ties sharing their average rank. */
function averageRanks(values: number[]): number[] {
  const order = values.map((v, i) => ({ v, i })).sort((a, b) => a.v - b.v);
  const ranks = new Array<number>(values.length).fill(0);
  for (let i = 0; i < order.length; ) {
    let j = i;
    while (j + 1 < order.length && order[j + 1]!.v === order[i]!.v) j++;
    const avg = (i + 1 + (j + 1)) / 2; // ranks i + 1 .. j + 1
    for (let k = i; k <= j; k++) ranks[order[k]!.i] = avg;
    i = j + 1;
  }
  return ranks;
}

/** Exact two-sided p: the null distribution of the positive-rank sum over all 2^n sign assignments. */
function exactP(ranks: number[], w: number, n: number): number {
  // Halved ranks (what ties produce) are doubled to make the subset sums integers.
  const scaled = ranks.map((r) => Math.round(r * 2));
  const total = scaled.reduce((a, b) => a + b, 0);
  const counts = new Float64Array(total + 1);
  counts[0] = 1;
  let reach = 0;
  for (const r of scaled) {
    for (let s = reach; s >= 0; s--) {
      const c = counts[s]!;
      if (c !== 0) counts[s + r] = counts[s + r]! + c;
    }
    reach += r;
  }
  const target = Math.round(w * 2);
  let low = 0;
  for (let s = 0; s <= target; s++) low += counts[s]!;
  let high = 0;
  for (let s = target; s <= total; s++) high += counts[s]!;
  return Math.min(1, (2 * Math.min(low, high)) / 2 ** n);
}

/** Normal approximation: continuity correction to the sum, standard tie correction to the variance. */
function normalP(ranks: number[], w: number, n: number): number {
  const mean = (n * (n + 1)) / 4;
  let tieSum = 0;
  for (let i = 0; i < ranks.length; ) {
    let j = i;
    while (j + 1 < ranks.length && ranks[j + 1] === ranks[i]) j++;
    tieSum += (j - i + 1) ** 3 - (j - i + 1);
    i = j + 1;
  }
  const variance = (n * (n + 1) * (2 * n + 1)) / 24 - tieSum / 48;
  if (variance <= 0) return 1;
  const z = Math.max(0, Math.abs(w - mean) - 0.5) / Math.sqrt(variance);
  return Math.min(1, 2 * (1 - normalCdf(z)));
}

/** Standard normal CDF, for the n > 20 branch. Exported so tests can check it against published values. */
export function normalCdf(z: number): number {
  return 0.5 * erfc(-z / Math.SQRT2);
}

/** Complementary error function, Chebyshev form (Numerical Recipes, §6.2). */
function erfc(x: number): number {
  return x >= 0 ? erfcPositive(x) : 2 - erfcPositive(-x);
}

const ERFC_COF = [
  -1.3026537197817094, 6.4196979235649026e-1, 1.9476473204185836e-2, -9.561514786808631e-3, -9.46595344482036e-4, 3.66839497852761e-4,
  4.2523324806907e-5, -2.0278578112534e-5, -1.624290004647e-6, 1.30365583558e-6, 1.5626441722e-8, -8.5238095915e-8, 6.529054439e-9,
  5.059343495e-9, -9.91364156e-10, -2.27365122e-10, 9.6467911e-11, 2.394038e-12, -6.886027e-12, 8.94487e-13, 3.13092e-13,
  -1.12708e-13, 3.81e-16, 7.106e-15,
];

function erfcPositive(z: number): number {
  const t = 2 / (2 + z);
  const ty = 4 * t - 2;
  let d = 0;
  let dd = 0;
  for (let j = ERFC_COF.length - 1; j > 0; j--) {
    const tmp = d;
    d = ty * d - dd + ERFC_COF[j]!;
    dd = tmp;
  }
  return t * Math.exp(-z * z + 0.5 * (ERFC_COF[0]! + ty * d) - dd);
}

// ---- the summary ----

export interface ForwardAnalysisPair {
  task: string;
  passOld: boolean;
  passNew: boolean;
  costOld: number | null;
  costNew: number | null;
  /** Reason the pair is invalid for both setups (DESIGN.md §"Forward run", invalidated tasks). */
  excluded?: string;
}

export interface ForwardSummary {
  /** Pairs counted: every pair that is not excluded. */
  n: number;
  excludedCount: number;
  /** Discordant counts: NEW passed and OLD failed, and the reverse. */
  newOnly: number;
  oldOnly: number;
  both: number;
  neither: number;
  /** McNemar exact two-sided p over newOnly vs oldOnly; 1 when there are no discordant pairs. */
  p: number;
  /** Whether a claim may be made at all: n >= 24, whatever p turns out to be. */
  claim: boolean;
  /** Wilcoxon signed-rank p on costNew - costOld, or null when no pair carries both costs. */
  costP: number | null;
  wording: string;
}

/** The forward result: the four counts, the McNemar p, the cost p and the sentence a report may print. */
export function forwardSummary(pairs: ForwardAnalysisPair[]): ForwardSummary {
  const counted = pairs.filter((p) => p.excluded === undefined);
  const newOnly = counted.filter((p) => p.passNew && !p.passOld).length;
  const oldOnly = counted.filter((p) => p.passOld && !p.passNew).length;
  const both = counted.filter((p) => p.passOld && p.passNew).length;
  const neither = counted.length - newOnly - oldOnly - both;
  const n = counted.length;
  const p = mcnemarExact(newOnly, oldOnly);

  const costed = counted.filter((p) => p.costOld !== null && p.costNew !== null);
  const costP = costed.length === 0 ? null : wilcoxonSignedRank(costed.map((p) => p.costNew! - p.costOld!)).p;

  const verdict = `${newOnly} vs ${oldOnly} passed, p = ${p.toFixed(3)}`;
  const wording = n < MIN_CLAIM_PAIRS ? `${verdict}; no claim: n = ${n} < ${MIN_CLAIM_PAIRS}` : p >= ALPHA ? `${verdict}; not significant at n = ${n}` : verdict;

  return { n, excludedCount: pairs.length - counted.length, newOnly, oldOnly, both, neither, p, claim: n >= MIN_CLAIM_PAIRS, costP, wording };
}
// F15: data helpers for the experiment page. The page reads the published forward-run results at
// public/data/self/forward.json (reports/self/forward.json in the repo), and the pre-registration hash at
// public/data/self/prereg.json. `loadForward` is pure over parsed JSON, so tests call it directly; the two
// *File helpers do the disk read and are what the page uses.
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";

/** One paired task in the forward run, as published. `old` is the demoted setup, `new` the promoted one. */
export interface ForwardRow {
  task: string;
  old: boolean;
  new: boolean;
  costOld: number | null;
  costNew: number | null;
  /** Present when the task was excluded from the comparison, holding the written reason. */
  excluded?: string;
}

export interface ForwardSummary {
  n: number;
  /** The published sentence. The page shows it verbatim, never reworded. */
  wording: string;
  /** Rows loadForward rejected as malformed. They are not in `rows`. */
  skipped: number;
}

export interface Forward {
  rows: ForwardRow[];
  summary: ForwardSummary | null;
}

const DATA = join(process.cwd(), "public", "data");

const object = (v: unknown): Record<string, unknown> | null =>
  typeof v === "object" && v !== null && !Array.isArray(v) ? (v as Record<string, unknown>) : null;

/** A cost is a finite number, null, or absent (an unpriced task). Anything else makes the row malformed. */
function cost(v: unknown): { ok: true; value: number | null } | { ok: false } {
  if (v === undefined || v === null) return { ok: true, value: null };
  if (typeof v === "number" && Number.isFinite(v)) return { ok: true, value: v };
  return { ok: false };
}

/** A well-formed pair, or null. A row missing its task or its two pass flags is not a pair. */
function row(raw: unknown): ForwardRow | null {
  const r = object(raw);
  if (!r) return null;
  if (typeof r.task !== "string" || r.task.length === 0) return null;
  if (typeof r.old !== "boolean" || typeof r.new !== "boolean") return null;
  const oldCost = cost(r.costOld);
  const newCost = cost(r.costNew);
  if (!oldCost.ok || !newCost.ok) return null;
  if (r.excluded !== undefined && typeof r.excluded !== "string") return null;
  const out: ForwardRow = { task: r.task, old: r.old, new: r.new, costOld: oldCost.value, costNew: newCost.value };
  if (r.excluded !== undefined) out.excluded = r.excluded;
  return out;
}

/** The summary with the skip count added, or null when the file has no usable summary. */
function summary(raw: unknown, skipped: number): ForwardSummary | null {
  const s = object(raw);
  if (!s) return null;
  if (typeof s.n !== "number" || !Number.isFinite(s.n) || typeof s.wording !== "string") return null;
  return { n: s.n, wording: s.wording, skipped };
}

/**
 * Parses a published forward.json. A row that is not a well-formed pair is dropped and counted in
 * `summary.skipped`. A missing or malformed summary gives null, so the page shows the rows without a claim.
 */
export function loadForward(json: unknown): Forward {
  const root = object(json);
  const rawRows = root && Array.isArray(root.rows) ? root.rows : [];
  const rows: ForwardRow[] = [];
  let skipped = 0;
  for (const raw of rawRows) {
    const normalized = row(raw);
    if (normalized) rows.push(normalized);
    else skipped++;
  }
  return { rows, summary: summary(root?.summary, skipped) };
}

function readJson(file: string): unknown {
  if (!existsSync(file)) return undefined;
  try {
    return JSON.parse(readFileSync(file, "utf8"));
  } catch {
    return undefined;
  }
}

/** The forward results under dataDir (default public/data), or null when the file is absent or unreadable. */
export function loadForwardFile(dataDir: string = DATA): Forward | null {
  const json = readJson(join(dataDir, "self", "forward.json"));
  return json === undefined ? null : loadForward(json);
}

const SHA256 = /^[0-9a-f]{64}$/i;
/** Keys the harness may publish the frozen backlog's hash under. Only a 64-hex value is ever shown. */
const SHA_KEYS = ["backlog_sha256", "backlogSha256", "sha256"] as const;

/**
 * The frozen backlog's sha256 from a prereg.json, or null. A value that is not a 64-hex string under a
 * recognised key is ignored, so a stray hash is never published as the backlog's.
 */
export function loadPrereg(json: unknown): string | null {
  const root = object(json);
  if (!root) return null;
  const nested = object(root.backlog);
  for (const key of SHA_KEYS) {
    const v = root[key] ?? nested?.[key];
    if (typeof v === "string" && SHA256.test(v)) return v.toLowerCase();
  }
  return null;
}

/** The frozen backlog's sha256 from prereg.json under dataDir, or null when it is absent or has no hash. */
export function loadPreregFile(dataDir: string = DATA): string | null {
  const json = readJson(join(dataDir, "self", "prereg.json"));
  return json === undefined ? null : loadPrereg(json);
}
// Forward harness (DESIGN.md §"Forward run", §"Stop rule"): each pre-registered backlog task runs through the old and
// the new setup in paired worktrees from one commit, both results are graded, the winner is merged, and the pair is recorded.
import { Database } from "bun:sqlite";
import { existsSync, mkdirSync, mkdtempSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, relative, resolve } from "node:path";
import { detectTestCmd, grade, isTestFile } from "../grade/index.ts";
import type { HiddenTest, StepRunner } from "../grade/index.ts";
import type { LlmClient } from "../llm/types.ts";
import { createSandbox, destroySandbox, runGit } from "../sandbox/index.ts";
import type { ForwardPair } from "../types.ts";
import { assignLabels, blindJudge, pairSeed, rng, secondaryOutcome } from "./blind.ts";
import type { MergeReason, Side } from "./blind.ts";
import { priceRunLog, runLogPath } from "./cost.ts";

export * from "./blind.ts";

export const DEFAULT_FORWARD_DB = ".roster/roster.db";
/**
 * Every grading step's time limit. grade()'s 5-minute default timed every forward suite run out (amendment 12), and
 * 45 minutes still killed suites while the machine ran agents, the queue and a regrade at once (amendment 15).
 */
export const FORWARD_STEP_TIMEOUT_MS = Number(process.env.ROSTER_GRADE_TIMEOUT_MS ?? 90 * 60_000);
/** Per-test timeout for bun in forward grading: bun's 5 s default fails tests on timing alone under load. */
export const FORWARD_BUN_TEST_TIMEOUT_MS = 60_000;
/**
 * Grading slots (amendment 13, machine-wide since amendment 15). Grading steps don't block the queue, so agents keep
 * launching while a pair grades. Two branches at a time (amendment 16): with the 90-minute step limit two suites fit
 * comfortably, and one slot made grading the bottleneck of the whole run.
 */
export const FORWARD_GRADE_PARALLEL = Number(process.env.ROSTER_GRADE_PARALLEL ?? 2);

/** The test command forward grading uses for a tree: bun gets a per-test timeout; undefined leaves detection to grade(). */
export function forwardTestCmd(dir: string): string | undefined {
  try {
    const cmd = detectTestCmd(dir);
    return cmd === "bun test" ? `bun test --timeout ${FORWARD_BUN_TEST_TIMEOUT_MS}` : cmd;
  } catch {
    return undefined;
  }
}
export const MIN_PAIRS = 15;
export const MIN_NET_LOSSES = 3;

export interface BacklogTask {
  id: string;
  /** The task text, without the setup tag line. */
  body: string;
  /** Paths from the task's OWNS line; the scope guard allows edits only there. Empty when the task names none. */
  owns: string[];
}

/** Task blocks sit between "<!-- Txx -->" and "<!-- /Txx -->", the format scripts/run-setup.sh reads. */
export function parseBacklog(text: string): BacklogTask[] {
  const tasks: BacklogTask[] = [];
  const re = /^<!-- (\S+) -->\n([\s\S]*?)^<!-- \/\1 -->/gm;
  for (const m of text.matchAll(re)) {
    const lines = m[2]!.replace(/\n+$/, "").split("\n");
    if (lines[0]?.startsWith("[roster ")) lines.shift();
    const body = lines.join("\n");
    const owns = /^OWNS:\s*(.+)$/m.exec(body)?.[1]?.split(/[,\s]+/).map((s) => s.replace(/[`.;]+$/g, "").replace(/^`/, "")).filter((s) => s.includes("/") || s.includes(".")) ?? [];
    tasks.push({ id: m[1]!, body, owns });
  }
  return tasks;
}

export const setupTag = (setup: string, task: string) => `[roster setup=${setup} task=${task}]`;

/** A backlog containing only `task`, tagged for `setup`, in the format scripts/run-setup.sh expects. */
export function taggedBlock(task: BacklogTask, setup: string): string {
  return `<!-- ${task.id} -->\n${setupTag(setup, task.id)}\n${task.body}\n<!-- /${task.id} -->\n`;
}

// ---- state ----

const EXTRA_COLUMNS = {
  suite_old: "INTEGER", suite_new: "INTEGER", scope_old: "INTEGER", scope_new: "INTEGER", merged_reason: "TEXT", secondary: "TEXT",
  agent_old_ms: "INTEGER", agent_new_ms: "INTEGER", grade_ms: "INTEGER",
};

const extraValues = (p: ForwardPair) => {
  const int = (b: boolean | null | undefined) => (b === null || b === undefined ? null : +b);
  return [
    int(p.suite_pass_old), int(p.suite_pass_new), int(p.scope_ok_old), int(p.scope_ok_new), p.merged_reason ?? null, p.secondary ?? null,
    p.agent_old_ms ?? null, p.agent_new_ms ?? null, p.grade_ms ?? null,
  ] as const;
};

export class ForwardStore {
  readonly db: Database;
  constructor(path: string) {
    if (path !== ":memory:") mkdirSync(dirname(resolve(path)), { recursive: true });
    this.db = new Database(path, { create: true });
    // The queue, a remerge/regrade and the wave-A copy can write the same file; wait for a lock instead of failing.
    this.db.exec("PRAGMA busy_timeout = 30000");
    this.db.exec(`CREATE TABLE IF NOT EXISTS forward_pairs (
      task_id TEXT PRIMARY KEY, setup_old TEXT NOT NULL, setup_new TEXT NOT NULL, pass_old INTEGER NOT NULL, pass_new INTEGER NOT NULL,
      cost_old REAL, cost_new REAL, merged TEXT, blind_labels TEXT NOT NULL, seed INTEGER NOT NULL, seq INTEGER NOT NULL)`);
    this.db.exec("CREATE TABLE IF NOT EXISTS forward_state (key TEXT PRIMARY KEY, value TEXT NOT NULL)");
    // Columns added by amendment 8 and the grading timings; databases from earlier runs gain them as NULL.
    const have = new Set((this.db.query("PRAGMA table_info(forward_pairs)").all() as { name: string }[]).map((c) => c.name));
    for (const [col, type] of Object.entries(EXTRA_COLUMNS)) if (!have.has(col)) this.db.exec(`ALTER TABLE forward_pairs ADD COLUMN ${col} ${type}`);
  }

  pairs(): ForwardPair[] {
    const rows = this.db.query("SELECT * FROM forward_pairs ORDER BY seq").all() as Record<string, unknown>[];
    const bool = (v: unknown) => (v === null || v === undefined ? null : v === 1);
    return rows.map((r) => ({
      task_id: r.task_id as string,
      setup_old: r.setup_old as string,
      setup_new: r.setup_new as string,
      pass_old: r.pass_old === 1,
      pass_new: r.pass_new === 1,
      cost_old: r.cost_old as number | null,
      cost_new: r.cost_new as number | null,
      merged: r.merged as "old" | "new" | null,
      blind_labels: JSON.parse(r.blind_labels as string),
      seed: r.seed as number,
      suite_pass_old: bool(r.suite_old),
      suite_pass_new: bool(r.suite_new),
      scope_ok_old: bool(r.scope_old),
      scope_ok_new: bool(r.scope_new),
      merged_reason: (r.merged_reason ?? null) as ForwardPair["merged_reason"],
      secondary: (r.secondary ?? null) as ForwardPair["secondary"],
      agent_old_ms: (r.agent_old_ms ?? null) as number | null,
      agent_new_ms: (r.agent_new_ms ?? null) as number | null,
      grade_ms: (r.grade_ms ?? null) as number | null,
    }));
  }

  addPair(p: ForwardPair): void {
    const seq = (this.db.query("SELECT COUNT(*) AS n FROM forward_pairs").get() as { n: number }).n;
    this.db
      .query(
        `INSERT OR REPLACE INTO forward_pairs (task_id, setup_old, setup_new, pass_old, pass_new, cost_old, cost_new, merged, blind_labels, seed, seq,
          suite_old, suite_new, scope_old, scope_new, merged_reason, secondary, agent_old_ms, agent_new_ms, grade_ms) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,
      )
      .run(p.task_id, p.setup_old, p.setup_new, +p.pass_old, +p.pass_new, p.cost_old, p.cost_new, p.merged, JSON.stringify(p.blind_labels), p.seed, seq, ...extraValues(p));
  }

  /** Rewrites a recorded pair's merge outcome (remerge). Costs and seq are left as recorded; H1 only with `withPass` (regrade). */
  updateMerge(p: ForwardPair, withPass = false): void {
    this.db
      .query("UPDATE forward_pairs SET suite_old=?, suite_new=?, scope_old=?, scope_new=?, merged_reason=?, secondary=?, agent_old_ms=?, agent_new_ms=?, grade_ms=?, merged=?, blind_labels=? WHERE task_id=?")
      .run(...extraValues(p), p.merged, JSON.stringify(p.blind_labels), p.task_id);
    if (withPass) this.db.query("UPDATE forward_pairs SET pass_old=?, pass_new=? WHERE task_id=?").run(+p.pass_old, +p.pass_new, p.task_id);
  }

  getState(key: string): string | null {
    return (this.db.query("SELECT value FROM forward_state WHERE key = ?").get(key) as { value: string } | null)?.value ?? null;
