1	// Generates docs/FACTS.md from reports/. A fact whose source file or path is missing prints PENDING, never a number.
2	import { existsSync, mkdirSync, readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
3	import { dirname, join } from "node:path";
4	
5	export type FactSpec = {
6	  key: string;
7	  /** Relative to reports/ (or to the repo root when base is "root"). Directory segments may contain "*". */
8	  file: string;
9	  /** "$.a.b[0]" or "$.a[*].b" (every array element), or "re:<regex>" with one capture group for text files. */
10	  path: string;
11	  base?: "reports" | "root";
12	  /** What to do with several values: sum them (numbers) or count them. Default: exactly one value. */
13	  agg?: "sum" | "count";
14	  /** Skip matched files that sit under a directory with one of these names. */
15	  exclude?: string[];
16	  unit?: string;
17	  /** Round numbers to this many decimals and say so in the line. */
18	  decimals?: number;
19	  /** A path whose values are booleans; when any is true the number is a lower bound and prints with "≥". */
20	  lowerBound?: string;
21	  /** Print this when the value is JSON null (instead of PENDING). */
22	  nullAs?: string;
23	};
24	
25	const SELF = "rajkaria__roster/review.json";
26	const REVIEW1 = "self/review-1/decisions.json";
27	const FORWARD = "self/forward.json";
28	const NOT_CORPUS = ["rajkaria__roster", "_sample"];
29	
30	// Public numbers. Add a spec here before publishing a number anywhere.
31	export const FACT_SPECS: FactSpec[] = [
32	  { key: "SELF_SESSIONS", file: SELF, path: "$.setups[*].sessions", agg: "sum", unit: "sessions" },
33	  { key: "SELF_MATURE", file: SELF, path: "$.setups[*].mature_sessions", agg: "sum", unit: "mature sessions" },
34	  { key: "SELF_SETUPS", file: SELF, path: "$.setups[*].setup_id", agg: "count", unit: "setups" },
35	  { key: "SELF_SPEND_USD", file: SELF, path: "$.setups[*].spend_usd", agg: "sum", unit: "USD", decimals: 2, lowerBound: "$.setups[*].spend_lower_bound" },
36	  { key: "SELF_LABEL", file: SELF, path: "$.label" },
37	  { key: "SELF_ODDS_RATIO", file: SELF, path: "$.odds_ratio", decimals: 2 },
38	  { key: "SELF_P", file: SELF, path: "$.p_value", decimals: 3 },
39	  { key: "CORPUS_REPOS", file: "*/review.json", path: "$.repo", agg: "count", exclude: NOT_CORPUS, unit: "repos" },
40	  { key: "CORPUS_SESSIONS", file: "*/review.json", path: "$.setups[*].sessions", agg: "sum", exclude: NOT_CORPUS, unit: "sessions" },
41	  { key: "REVIEW1_OUTCOME", file: REVIEW1, path: "$.outcome" },
42	  { key: "REVIEW1_PROMOTED", file: REVIEW1, path: "$.promoted", nullAs: "none" },
43	  { key: "REVIEW1_REPLAYS", file: REVIEW1, path: "$.decisions[*].candidate", agg: "count", unit: "candidate replays gated" },
44	  { key: "REVIEW1_SPEND_USD", file: REVIEW1, path: "$.spent.total_usd", unit: "USD", decimals: 2 },
45	  { key: "FORWARD_PAIRS_N", file: FORWARD, path: "$.pairs.n", unit: "pairs" },
46	  { key: "FORWARD_NEW_ONLY", file: FORWARD, path: "$.mcnemar.new_only", unit: "pairs" },
47	  { key: "FORWARD_OLD_ONLY", file: FORWARD, path: "$.mcnemar.old_only", unit: "pairs" },
48	  { key: "FORWARD_P", file: FORWARD, path: "$.mcnemar.p", decimals: 3 },
49	  { key: "FORWARD_WORDING", file: FORWARD, path: "$.wording" },
50	  { key: "BACKLOG_SHA256", file: "experiments/FREEZE.txt", base: "root", path: "re:^forward-backlog\\.md\\s+sha256\\s+([0-9a-f]{64})\\s*$" },
51	];
52	
53	type Tok = string | number;
54	
55	function tokens(path: string): Tok[] | undefined {
56	  if (!path.startsWith("$")) return undefined;
57	  const out: Tok[] = [];
58	  for (const m of path.slice(1).matchAll(/\.([^.[\]]+)|\[(\d+|\*)\]/g)) out.push(m[2] !== undefined ? (m[2] === "*" ? "*" : Number(m[2])) : (m[1] as string));
59	  return out;
60	}
61	
62	/** Every value the path reaches; "[*]" fans out over array elements. Empty when the path is not present. */
63	export function resolve(data: unknown, path: string): unknown[] {
64	  const toks = tokens(path);
65	  if (!toks) return [];
66	  let cur: unknown[] = [data];
67	  for (const t of toks) {
68	    const next: unknown[] = [];
69	    for (const c of cur) {
70	      if (c === null || typeof c !== "object") continue;
71	      if (t === "*") {
72	        if (Array.isArray(c)) next.push(...c);
73	      } else if (t in c) next.push((c as any)[t]);
74	    }
75	    cur = next;
76	  }
77	  return cur;
78	}
79	
80	export function lookup(data: unknown, path: string): number | string | boolean | undefined {
81	  if (path.includes("[*]")) return undefined;
82	  const [v] = resolve(data, path);
83	  return typeof v === "number" || typeof v === "string" || typeof v === "boolean" ? v : undefined;
84	}
85	
86	const segRegex = (seg: string) => new RegExp("^" + seg.split("*").map((p) => p.replace(/[.+?^${}()|[\]\\]/g, "\\$&")).join(".*") + "$");
87	
88	/** Expands "*" in path segments against the disk. Returns paths relative to root, sorted. */
89	export function expand(root: string, file: string): string[] {
90	  let acc = [""];
91	  for (const seg of file.split("/")) {
92	    const next: string[] = [];
93	    for (const base of acc) {
94	      const rel = (n: string) => (base ? `${base}/${n}` : n);
95	      if (!seg.includes("*")) {
96	        if (existsSync(join(root, rel(seg)))) next.push(rel(seg));
97	        continue;
98	      }
99	      const dir = join(root, base);
100	      if (!existsSync(dir) || !statSync(dir).isDirectory()) continue;
101	      const rx = segRegex(seg);
102	      for (const n of readdirSync(dir).sort()) if (rx.test(n)) next.push(rel(n));
103	    }
104	    acc = next;
105	  }
106	  return acc;
107	}
108	
109	/** The printed value, or undefined for PENDING. */
110	function factValue(root: string, s: FactSpec): string | undefined {
111	  const files = expand(root, s.file).filter((f) => statSync(join(root, f)).isFile() && !(s.exclude ?? []).some((x) => f.split("/").includes(x)));
112	  if (files.length === 0) return undefined;
113	  const values: unknown[] = [];
114	  const bounds: unknown[] = [];
115	  for (const f of files) {
116	    const text = readFileSync(join(root, f), "utf8");
117	    if (s.path.startsWith("re:")) {
118	      const m = new RegExp(s.path.slice(3), "m").exec(text);
119	      if (!m?.[1]) return undefined;
120	      values.push(m[1]);
121	      continue;
122	    }
123	    let data: unknown;
124	    try {
125	      data = JSON.parse(text);
126	    } catch {
127	      return undefined;
128	    }
129	    const got = resolve(data, s.path);
130	    // A file missing the path must not silently shrink a total; an existing but empty array contributes nothing.
131	    const fan = s.path.lastIndexOf("[*]");
132	    const isEmptyArray = fan >= 0 && resolve(data, s.path.slice(0, fan)).some(Array.isArray);
133	    if (got.length === 0 && !(isEmptyArray && s.agg)) return undefined;
134	    values.push(...got);
135	    if (s.lowerBound) bounds.push(...resolve(data, s.lowerBound));
136	  }
137	  let v: unknown;
138	  if (s.agg === "count") v = values.length;
139	  else if (s.agg === "sum") {
140	    if (!values.every((x) => typeof x === "number" && Number.isFinite(x))) return undefined;
141	    v = (values as number[]).reduce((a, b) => a + b, 0);
142	  } else {
143	    if (values.length !== 1) return undefined;
144	    v = values[0];
145	    if (v === null) return s.nullAs;
146	  }
147	  if (typeof v === "number") {
148	    const num = s.decimals !== undefined ? v.toFixed(s.decimals) : String(v);
149	    const lb = bounds.some((b) => b === true) ? "≥" : "";
150	    const unit = s.unit ? ` ${s.unit}` : "";
151	    return `${lb}${num}${unit}${s.decimals !== undefined ? `, rounded to ${s.decimals} decimals` : ""}`;
152	  }
153	  return typeof v === "string" || typeof v === "boolean" ? String(v) : undefined;
154	}
155	
156	export function renderFacts(reportsDir: string, specs: FactSpec[], ts: string): string {
157	  const lines = specs.map((s) => {
158	    const root = s.base === "root" ? join(reportsDir, "..") : reportsDir;
159	    let value: string | undefined;
160	    try {
161	      value = factValue(root, s);
162	    } catch {
163	      value = undefined;
164	    }
165	    const src = `${s.base === "root" ? "" : "reports/"}${s.file}#${s.path}`;
166	    const ex = s.exclude?.length ? `, excluding ${s.exclude.join(", ")}` : "";
167	    return `${s.key} = ${value === undefined ? "PENDING" : value}  (source: ${src}${ex}, generated ${ts})`;
168	  });
169	  return [
170	    "<!-- GENERATED by scripts/facts.ts from reports/. Do not edit by hand. -->",
171	    "# Facts",
172	    "",
173	    ...lines,
174	    "",
175	  ].join("\n");
176	}
177	
178	export function writeFacts(
179	  reportsDir = "reports",
180	  out = "docs/FACTS.md",
181	  specs = FACT_SPECS,
182	  ts = new Date().toISOString(),
183	): string {
184	  const text = renderFacts(reportsDir, specs, ts);
185	  mkdirSync(dirname(out), { recursive: true });
186	  writeFileSync(out, text);
187	  return text;
188	}
189	
190	if (import.meta.main) {
191	  writeFacts();
192	  console.log("wrote docs/FACTS.md");
193	}
194

